mapper.select:
SELECT c.id, c.article_id, c.user_id, c.parent_id, c.content, c.status, c.admin_remark, c.reviewed_at, c.created_at,
       u.nickname AS author_name, u.avatar_url AS author_avatar,
       (CASE WHEN UPPER(COALESCE(u.role, '')) = 'ADMIN' THEN 1 ELSE 0 END) AS is_admin
FROM article_comments c
LEFT JOIN users u ON c.user_id = u.id

    
        AND c.status = #{status}
    
    
        AND c.article_id = #{articleId}
    

ORDER BY c.created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM article_comments c

    
        AND c.status = #{status}
    
    
        AND c.article_id = #{articleId}
